import json
try:
    rows = {json.loads(l).get('doi'): json.loads(l) for l in open('/app/result.jsonl') if l.strip()}
    a2 = rows.get('10.1000/a2', {})
    score = a2.get('score')
    print('CORRECT_5.0' if score == 5.0 else f'WRONG_{score}')
